package com.company.leadershipintelligence.api.request;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.Instant;
import java.util.List;

/**
 * The body of {@code POST /calculate} (decisions D10, D13, D14, D45). It has no tenant, assessment id, configuration or
 * weights: unknown fields are rejected, the tenant comes from the token, and the assessment id is generated by the
 * server. An optional {@code questionType} per answer is only checked against the configured definition.
 *
 * <p>Answers come in one of two forms, never both. {@code inputs} is one answer per question for the organization.
 * {@code responses} are answers with a scope: MEMBER (one respondent, no identity), TEAM or ORGANIZATION (a figure
 * already combined by the caller, optionally with the number of respondents it represents).
 */
@ExactlyOneAnswerList
public record CalculateRequest(
        @NotNull @Valid AssessmentPart assessment,
        @Size(max = 1000) @Valid List<InputPart> inputs,
        @Size(max = 20000) @Valid List<ResponsePart> responses) {

    public record AssessmentPart(
            @NotBlank @Size(max = 64) String organizationId,
            @NotBlank @Size(max = 64) String templateId,
            @NotBlank @Size(max = 20) String templateVersion,
            @NotBlank @Size(max = 32) String status,
            Instant completedAt) {
    }

    public record InputPart(
            @NotBlank @Size(max = 64) String questionId,
            Object answer,
            @Size(max = 32) String questionType) {
    }

    /**
     * @param scope       MEMBER, TEAM or ORGANIZATION
     * @param teamId      required for TEAM, optional for MEMBER, not allowed for ORGANIZATION
     * @param respondents how many people a TEAM or ORGANIZATION figure represents; not allowed for MEMBER
     */
    public record ResponsePart(
            @NotBlank @Size(max = 64) String questionId,
            Object answer,
            @Size(max = 32) String questionType,
            @NotBlank @Size(max = 16) String scope,
            @Size(max = 64) String teamId,
            @Min(1) Integer respondents) {
    }
}
